import React, { useState } from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    ActivityIndicator
} from 'react-native';

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

import api from '../../../services/api';
import { useLoadPage } from '../../../hooks/loadPage';

interface response {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
    }[]
};

export function PaymentMenu() {
    const {
        shoppingCartItem,
        selectedNumber,
        paymentMenuActive,
        loginValue,
        listData,
        getList
    } = useContexState();

    const {
        setShoppingCartItem,
        setPaymentMenuActive,
        setRegisterMenuActive,
        setAlertActive,
        setAlertMessage
    } = useContexState();

    const [load, setLoad] = useState(false);
    const [loadMessage, setLoadMessage] = useState('')

    const responceCard = getList[String(selectedNumber)]?.[0];
    const { LoadPage } = useLoadPage()


    function LoadPopUp() {
        return (
            <>
                <Text style={styles.textLoadPopUp}>{loadMessage}</Text>
                <ActivityIndicator
                    size={37}
                    color='#fff'
                    style={styles.ActivityIndicator}
                />
            </>
        );
    };


    function ResponceClick(responce: response) {
        if (responceCard && responce.data.length === 0) {
            LoadPage(Number(listData[0]?.firstCard));
        } else if (!responceCard && responce.data.length !== 0) {
            LoadPage(Number(listData[0]?.firstCard));
        };
    };



    function ApproveCard() {
        setLoadMessage('Aprovando número!');
        setLoad(true);

        api.get("approveCard", {
            params: {
                number: selectedNumber,
                name: loginValue.name,
                password: loginValue.password
            }
        }).then((responce: response) => {
            setPaymentMenuActive(false);

            api.get("getCards", {
                params: {
                    firstNumber: selectedNumber,
                    lastNumber: selectedNumber,
                }
            }).then(ResponceClick);


            setLoad(false);
        });
    };


    function RejectCard() {
        setLoadMessage('Rejeitando número!');
        setLoad(true);

        api.get("rejectCard", {
            params: {
                number: selectedNumber,
                name: loginValue.name,
                password: loginValue.password
            }
        }).then((responce) => {
            LoadPage(Number(listData[0].firstCard));
            setPaymentMenuActive(false);
            setLoad(false);
        });
    };


    function AddToCart(message: string) {
        setLoadMessage(message);
        setLoad(true);
        if (loginValue.permission === 'adm') {
            setShoppingCartItem([...shoppingCartItem, Number(selectedNumber)]);
            setLoad(false);
            setPaymentMenuActive(false);
        } else {
            api.post("registerBuy", {
                number: selectedNumber,
                name: 'Number added to cart',
                phone: '(__)_________',
            }).then((response) => {
                if (message === 'Preparando o seu número!') {
                    setRegisterMenuActive(true);
                };
                setLoad(false);
                setPaymentMenuActive(false);
                setShoppingCartItem([...shoppingCartItem, Number(selectedNumber)]);

            });
        };
    };


    function AlertMessageAbout() {

        if (responceCard.name === 'Number added to cart') {
            return (`O número consta como no carrinho!
            \nMomento\n${responceCard.created_at}`);
        };

        return (`Nome\n${responceCard.name}
        \nTelefone\n${responceCard.phone}
        \nPreço\n${responceCard.price}
        \nMomento\n${responceCard.created_at}`);
    };



    function Menu() {
        function ValidateButton() {
            return (
                <TouchableOpacity
                    onPress={() => {
                        setPaymentMenuActive(false);
                        setRegisterMenuActive(true);
                        setShoppingCartItem([...shoppingCartItem, Number(selectedNumber)]);
                    }}
                    style={[styles.containerButtonPurchase, {
                        backgroundColor: '#F4A900',
                        marginBottom: 10
                    }]} >
                    <Text style={styles.textButtonPurchase}>Validar</Text>
                </TouchableOpacity>
            );
        };

        function ApproveButton() {
            return (
                <TouchableOpacity
                    onPress={() => ApproveCard()}
                    style={[styles.containerButtonPurchase, {
                        backgroundColor: '#17A2B7',
                        marginBottom: 10
                    }]} >
                    <Text style={styles.textButtonPurchase}>Aprovar</Text>
                </TouchableOpacity>
            );
        };

        function AboutButton() {
            return (
                <TouchableOpacity
                    onPress={() => {
                        setAlertActive(true);
                        setAlertMessage(AlertMessageAbout());
                    }}
                    style={[styles.containerButtonPurchase, {
                        backgroundColor: '#6C7A86',
                        marginBottom: 10
                    }]} >
                    <Text style={styles.textButtonPurchase}>Sobre</Text>
                </TouchableOpacity>
            );
        };

        function RejectButton() {
            return (
                <TouchableOpacity
                    onPress={() => RejectCard()}
                    style={[styles.containerButtonPurchase, {
                        backgroundColor: '#FF6961'
                    }]} >
                    <Text style={styles.textButtonPurchase}>Rejeitar</Text>
                </TouchableOpacity>
            );
        };

        function BuyButton() {
            return (
                <TouchableOpacity
                    onPress={() => AddToCart('Preparando o seu número!')}
                    style={[styles.containerButtonPurchase, {
                        backgroundColor: '#26A744'
                    }]} >
                    <Text style={styles.textButtonPurchase}>Comprar</Text>
                </TouchableOpacity>
            );
        };

        function AddCartButton() {
            return (
                <TouchableOpacity
                    onPress={() => AddToCart('Adicionando ao carrinho!')}
                    style={styles.containerButtonAddCart} >
                    <Text style={styles.textButtonAddCart}>Adicionar ao {'\n'}carrinho</Text>
                </TouchableOpacity>
            );
        };

        function SelectMenuUser() {
            if (loginValue.permission === 'adm') {
                return (
                    <>
                        <AboutButton />
                        {responceCard.name === 'Number added to cart'
                            ? <ValidateButton />
                            : <ApproveButton />}
                        <RejectButton />
                    </>
                );
            } else return <BuyButton />;
        };


        return (
            <>
                <SelectMenuUser />
                <AddCartButton />
            </>
        );
    };






    return paymentMenuActive ? (
        <>
            <TouchableOpacity onPress={() => {
                setPaymentMenuActive(false);
            }} style={styles.containeMain} />

            <View style={styles.container} >
                <Text style={[styles.listText]}>{
                    (`0000${selectedNumber}`).slice(-4)
                }</Text>
                {load ? <LoadPopUp /> : <Menu />}
            </View>
        </>
    ) : null;
};
